using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;
using Pgvector;

namespace EnterpriseNexus.Domain.Entities;

public sealed class DocumentChunk
{
    public Guid Id { get; init; } = Guid.NewGuid();
    public Guid TenantId { get; init; }
    public Guid DocumentId { get; init; }

    public int ChunkIndex { get; init; }

    [Required]
    public string Content { get; set; } = string.Empty;

    public int TokenCount { get; init; }

    // 1536-dimension vector for OpenAI text-embedding-3-small
    [Column(TypeName = "vector(1536)")]
    public Vector Embedding { get; set; } = null!;

    // Access Control List (e.g., ["Finance-Admins", "Executive-Staff"])
    public string[] SecurityGroups { get; set; } = [];

    public DateTime CreatedAt { get; init; } = DateTime.UtcNow;

    // Navigation property
    public Document Document { get; set; } = null!;
}

public sealed class ConversationSession
{
    public Guid Id { get; init; } = Guid.NewGuid();
    public Guid TenantId { get; init; }
    public Guid UserId { get; init; }
    public string Title { get; set; } = "New Conversation";

    public List<Message> Messages { get; set; } = [];
    public DateTime CreatedAt { get; init; } = DateTime.UtcNow;
    public DateTime UpdatedAt { get; set; } = DateTime.UtcNow;
}

public sealed class Message
{
    public Guid Id { get; init; } = Guid.NewGuid();
    public Guid SessionId { get; init; }
    public string Role { get; init; } = "user"; // user | assistant | system | tool
    public string Content { get; set; } = string.Empty;

    public int PromptTokens { get; init; }
    public int CompletionTokens { get; init; }
    public long LatencyMs { get; init; }

    public List<Citation> Citations { get; set; } = [];
    public DateTime CreatedAt { get; init; } = DateTime.UtcNow;
}
